<?php use Sigesp\Core\{Csrf,Flash,View}; $flash=Flash::pull(); ?><div class="auth-title"><h2>Bem-vindo de volta</h2><p>Acesse o ambiente administrativo.</p></div><?php if($flash): ?><div class="alert error"><?= View::e($flash['message']) ?></div><?php endif; ?><form method="post" action="/login" class="form" data-loading-form><input type="hidden" name="_token" value="<?= Csrf::token() ?>"><label>CPF ou e-mail<input name="identificador" autocomplete="username" required></label><label>Senha<span class="password-field"><input name="senha" type="password" autocomplete="current-password" required minlength="8"><button type="button" data-password-toggle>Mostrar</button></span></label><button class="primary" type="submit">Entrar</button><a href="/recuperar-senha">Esqueci minha senha</a></form>
